import itertools

def solve(n):
    nums = list(range(1, 2*n + 1))
    for p in itertools.permutations(nums):
        pairs = []
        for i in range(n):
            pairs.append((p[2*i], p[2*i+1]))

        diffs = sorted([abs(a - b) for a, b in pairs])
        if diffs == list(range(1, n + 1)):
            return True
    return False

for n in range(1, 10):
    print(f"n={n}: {solve(n)}")

